  $import$::jsonb) as x(
    source text, nom text, categorie text, sous_cat text, nb_parts int,
    temps_prepa int, temps_cuisson int, temps_repos int, temps_total int, temperature int,
    ingredients jsonb, etapes text[], allergenes text[], tags text[], notes text
  )
)
insert into public.food_recettes
  (nom, categorie, sous_cat, nb_parts, temps_prepa, temps_cuisson, temps_repos, temps_total, temperature,
   ingredients, etapes, allergenes, tags, statut, source, source_type, notes, date_import)
select d.nom, d.categorie, d.sous_cat, d.nb_parts, d.temps_prepa, d.temps_cuisson, d.temps_repos, d.temps_total, d.temperature,
  d.ingredients, d.etapes, d.allergenes, d.tags,
  'brouillon', d.source, 'import_fiches_bellafood', d.notes, current_date
from donnees d
where not exists (
  select 1 from public.food_recettes fr where fr.source = d.source
);

